/** Component events and the cue each plays (tokens `sound-<event>`). A null cue is silent by design. */
enum class LeafySoundEvent(val cue: LeafyCue?) {
    /** Switch turned on; IconButton toggle selected. */
    ToggleOn(LeafyCue.ToggleOn),
    /** Switch turned off; IconButton toggle cleared. */
    ToggleOff(LeafyCue.ToggleOff),
    /** Checkbox checked. */
    Check(LeafyCue.Check),
    /** Checkbox cleared. */
    Uncheck(LeafyCue.Uncheck),
    /** Radio chosen; filter Chip, SegmentedButton option, selectable Tile or DataTable row selected. */
    Select(LeafyCue.Select),
    /** Filter Chip, SegmentedButton option (multiple), selectable Tile or DataTable row cleared. */
    Deselect(LeafyCue.Deselect),
    /** DataTable column sort changed. */
    Sort(LeafyCue.Reorder),
    /** Dialog or Menu opens. */
    Open(LeafyCue.Open),
    /** Dialog or Menu closes (keep the component mounted and set open to false, or there is nothing to play it). */
    Close(LeafyCue.Close),
    /** Accordion item or SideNav group opens. */
    Expand(LeafyCue.Expand),
    /** Accordion item or SideNav group closes. */
    Collapse(LeafyCue.Collapse),
    /** A success Notification appears (toasts always; inline ones with sound). */
    NotifySuccess(LeafyCue.Success),
    /** An error Notification appears. */
    NotifyError(LeafyCue.Error),
    /** A warning Notification appears. */
    NotifyWarning(LeafyCue.Warning),
    /** An info Notification appears. */
    NotifyInfo(LeafyCue.Info),
    /** A Snackbar appears. */
    Snackbar(LeafyCue.Notification),
    /** A Tag or input Chip is removed. Deliberately not delete: removing a filter loses nothing. */
    Remove(LeafyCue.Deselect),
    /** CodeSnippet copied to the clipboard. */
    Copy(LeafyCue.Copy),
    /** SearchBar cleared. */
    Clear(LeafyCue.Cancel),
    /** ProgressIndicator moves forward one step. */
    Step(LeafyCue.ProgressStep),
    /** ProgressIndicator moves past its last step; Progress reaches 100% (only with sound). */
    Complete(LeafyCue.Complete),
    /** Button, IconButton and FAB clicks. Silent: the result of the action makes the sound, not the press. */
    Press(null),
    /** Keystrokes in TextField and SearchBar. Silent; key clicks tire people within minutes. */
    Typing(null),
    /** Tabs switched. Silent: the new panel is the feedback. */
    TabChange(null),
    /** NavigationBar, NavigationRail, SideNav and Pagination moves. Silent: moving around is not an outcome. */
    Navigate(null),
}

